#!/usr/bin/env python3
# -*- coding: UTF-8 -*-
# ROOHPHISHER Encoded Payload – Sir Roohulamin 😈🔥
import zlib, base64, os, sys

# Encoded blob (compressed + base64)
_encoded = ""

try:
    _decoded = zlib.decompress(base64.b64decode(_encoded.encode('ascii')))
    exec(_decoded)
except Exception as e:
    print(f"[!] Decoding failed: {e}")
    sys.exit(1)
